export function academicResult(v){if((v.resultMode||'concept')==='concept'){if(!['A','B','C','D'].includes(v.concept))throw Error('Conceito inválido.');return{resultMode:'concept',concept:v.concept,score:null,maxScore:null,percent:null};}if(v.resultMode!=='numeric'||!Number.isFinite(v.score)||!Number.isFinite(v.maxScore)||v.maxScore<=0||v.maxScore>1000||v.score<0||v.score>v.maxScore)throw Error('Nota ou escala inválida.');return{resultMode:'numeric',concept:null,score:v.score,maxScore:v.maxScore,percent:v.score/v.maxScore*100};}
export function studentRisk(manual,exams){const cells=new Map(),evidence=[];for(const m of manual){const key=m.periodId+'|'+(m.subjectId||'geral');cells.set(key,[...(cells.get(key)||[]),m]);}for(const[key,values]of cells){const [period,subject]=key.split('|');if(subject==='geral'&&([...cells.keys()].some(k=>k.startsWith(period+'|')&&k!==key)||exams.some(e=>e.periodId===period)))continue;const conceptD=values.some(v=>(v.resultMode||'concept')==='concept'&&v.concept==='D'),lowNumeric=values.some(v=>v.resultMode==='numeric'&&v.percent<70);if(conceptD||lowNumeric)evidence.push({key,conceptD,lowNumeric});}const seen=new Set();for(const e of exams){if(!e.published||seen.has(e.examId)||cells.has(e.periodId+'|'+e.subjectId))continue;seen.add(e.examId);const conceptD=e.mode!=='numeric'&&e.concept==='D',lowNumeric=e.mode==='numeric'&&Number.isFinite(e.percent)&&e.percent<70;if(conceptD||lowNumeric)evidence.push({key:e.examId,conceptD,lowNumeric});}const dCount=evidence.filter(e=>e.conceptD).length,lowNumericCount=evidence.filter(e=>e.lowNumeric).length;return{dCount,lowNumericCount,red:dCount>=2||lowNumericCount>0,evidence};}
